'use client';
import { useEffect, useState } from 'react';
export default function Favorite({ id }: { id: string }) {
  const [saved, setSaved] = useState(false);
  const [ready, setReady] = useState(false);
  const [error, setError] = useState('');
  useEffect(() => {
    try { setSaved(localStorage.getItem('favorite:' + id) === '1'); }
    catch { setError('Cannot read favorites'); }
    setReady(true);
  }, [id]);
  function toggle() {
    try {
      localStorage.setItem('favorite:' + id, saved ? '0' : '1');
      setSaved(!saved); setError('');
    } catch { setError('Cannot save favorite'); }
  }
  return <div><button disabled={!ready} aria-pressed={saved} onClick={toggle}>
    {saved ? 'Saved' : 'Save channel'}
  </button>{error && <p role="alert">{error}</p>}</div>;
}

