import assert from 'node:assert/strict';
const base = 'http://localhost:3000';
const response = await fetch(base + '/api/channels?id=demo');
assert.equal(response.status, 200);
const channel = await response.json();
assert.equal(channel.id, 'demo');
assert.equal((await fetch(base + '/api/channels?id=missing')).status, 404);
const playlist = await fetch(base + channel.stream);
assert.equal(playlist.status, 200);
const text = await playlist.text();
assert(text.startsWith('#EXTM3U'));
for (const line of text.split(/\r?\n/).filter(x => x && !x.startsWith('#'))) {
  assert.equal((await fetch(new URL(line, base + channel.stream))).status, 200);
}
console.log('Catalog, playlist and all segments passed');

